function singleCandle(title: string, bars: Bar[], parameters: Parameters): SeriesMap {
  const bodyLimit = numberParameter(parameters, "body_ratio", 0.05, { minimum: 0, maximum: 1 });
  const shadowLimit = numberParameter(parameters, "shadow_ratio", 0.35, { minimum: 0, maximum: 1 });
  const shadowBody = numberParameter(parameters, "shadow_body_multiple", 2, { minimum: 0 });
  const tick = numberParameter(parameters, "tick_tolerance", 0.01, { minimum: 0 });
  const labels: Array<string | null> = [];
  const score: NullableNumber[] = [];
  for (const bar of bars) {
    const { open, high, low, close } = bar;
    const span = high - low;
    const body = Math.abs(close - open);
    const upper = high - Math.max(open, close);
    const lower = Math.min(open, close) - low;
    let matched = false;
    let direction = "neutral";
    let value: number | null;
    if (title === "Long-Legged Doji" && span > 0) {
      matched = body / span <= bodyLimit && upper / span >= shadowLimit && lower / span >= shadowLimit;
      value = Math.min(bodyLimit - body / span, upper / span - shadowLimit, lower / span - shadowLimit);
    } else if (title === "Four-Price Doji") {
      matched = high - low <= tick && Math.abs(open - close) <= tick;
      value = tick - Math.max(high - low, Math.abs(open - close));
    } else if (title === "High-Wave Candle" && span > 0) {
      matched = body / span <= bodyLimit && (body === 0 || (upper / body >= shadowBody && lower / body >= shadowBody));
      value = bodyLimit - body / span;
    } else if (title === "Belt Hold" && span > 0) {
      const bullish = close > open && open - low <= tick && body / span >= 0.6;
      const bearish = close < open && high - open <= tick && body / span >= 0.6;
      matched = bullish || bearish;
      direction = bullish ? "bullish" : bearish ? "bearish" : "neutral";
      value = body / span;
    } else {
      value = null;
    }
    labels.push(matched ? direction : "none");
    score.push(value);
  }
  return { label: labels, score };
}

function candlePatterns(title: string, bars: Bar[], parameters: Parameters): SeriesMap {
  const tick = numberParameter(parameters, "tick_tolerance", 0.01, { minimum: 0 });
  const bodyRatio = numberParameter(parameters, "doji_body_ratio", 0.05, { minimum: 0, maximum: 1 });
  let minimum = ["Harami Cross", "Kicking Pattern", "Matching Low", "Rising/Falling Window"].includes(title) ? 2 : 3;
  if (title === "Three-Line Strike") minimum = 4;
  if (["Rising/Falling Three Methods", "Mat Hold"].includes(title)) minimum = 5;
  const labels: Array<string | null> = Array(bars.length).fill(null);
  const matched: Array<boolean | null> = Array(bars.length).fill(null);
  for (let index = minimum - 1; index < bars.length; index++) {
    const window = bars.slice(index - minimum + 1, index + 1);
    const colors = window.map((bar) => bar.close > bar.open ? 1 : bar.close < bar.open ? -1 : 0);
    const bodies = window.map((bar) => [Math.min(bar.open, bar.close), Math.max(bar.open, bar.close)] as const);
    const spans = window.map((bar) => bar.high - bar.low);
    let ok = false;
    let direction = "none";
    if (title === "Harami Cross") {
      const [first, second] = window;
      const doji = spans[1] > 0 && Math.abs(second.close - second.open) / spans[1] <= bodyRatio;
      ok = doji && bodies[1][0] >= bodies[0][0] - tick && bodies[1][1] <= bodies[0][1] + tick;
      direction = colors[0] < 0 ? "bullish" : colors[0] > 0 ? "bearish" : "none";
    } else if (title === "Kicking Pattern") {
      const [first, second] = window;
      const nearMarubozu = window.every((bar, offset) => spans[offset] > 0 && Math.abs(bar.close - bar.open) / spans[offset] >= 0.8);
      const gap = second.low > first.high + tick || second.high < first.low - tick;
      ok = nearMarubozu && colors[0] * colors[1] === -1 && gap;
      direction = colors[1] > 0 ? "bullish" : "bearish";
    } else if (title === "Matching Low") {
      ok = numbersEqual(colors, [-1, -1]) && Math.abs(window[1].close - window[0].close) <= tick;
      direction = ok ? "bullish" : "none";
    } else if (title === "Rising/Falling Window") {
      const rising = window[1].low > window[0].high + tick;
      const falling = window[1].high < window[0].low - tick;
      ok = rising || falling;
      direction = rising ? "rising" : falling ? "falling" : "none";
    } else if (title === "Morning Doji Star" || title === "Evening Doji Star") {
      const [first, middle, last] = window;
      const middleDoji = spans[1] > 0 && Math.abs(middle.close - middle.open) / spans[1] <= bodyRatio;
      const midpoint = (first.open + first.close) / 2;
      if (title.startsWith("Morning")) {
        ok = colors[0] < 0 && middleDoji && colors[2] > 0 && last.close > midpoint;
        direction = "bullish";
      } else {
        ok = colors[0] > 0 && middleDoji && colors[2] < 0 && last.close < midpoint;
        direction = "bearish";
      }
    } else if (title === "Three-Line Strike") {
      const up = numbersEqual(colors.slice(0, 3), [1, 1, 1]) && colors[3] === -1 && bodies[3][0] <= bodies[0][0] && bodies[3][1] >= bodies[2][1];
      const down = numbersEqual(colors.slice(0, 3), [-1, -1, -1]) && colors[3] === 1 && bodies[3][0] <= bodies[2][0] && bodies[3][1] >= bodies[0][1];
      ok = up || down;
      direction = up ? "bearish-strike" : down ? "bullish-strike" : "none";
    } else if (title === "Rising/Falling Three Methods") {
      const insideFirst = window.slice(1, 4).every((bar) => bar.high <= window[0].high + tick && bar.low >= window[0].low - tick);
      const up = colors[0] > 0 && colors[4] > 0 && insideFirst && window[4].close > window[0].close;
      const down = colors[0] < 0 && colors[4] < 0 && insideFirst && window[4].close < window[0].close;
      ok = up || down;
      direction = up ? "rising" : down ? "falling" : "none";
    } else if (title === "Upside Gap Two Crows") {
      ok = numbersEqual(colors, [1, -1, -1]) && window[1].low > window[0].high && window[2].open > window[1].open && bodies[0][0] < window[2].close && window[2].close < bodies[0][1];
      direction = ok ? "bearish" : "none";
    } else if (title === "Mat Hold") {
      ok = colors[0] > 0 && window[1].low > window[0].close && window.slice(1, 4).every((bar) => bar.low > bodies[0][0]) && colors[4] > 0 && window[4].close > Math.max(...window.slice(0, 4).map((bar) => bar.high));
      direction = ok ? "bullish" : "none";
    }
    labels[index] = ok ? direction : "none";
    matched[index] = ok;
  }
  return { label: labels, matched };
}

function priceTransforms(title: string, bars: Bar[], parameters: Parameters): SeriesMap {
  const open = bars.map((bar) => bar.open);
  const high = bars.map((bar) => bar.high);
  const low = bars.map((bar) => bar.low);
  const close = bars.map((bar) => bar.close);
  if (title === "Typical Price") return { value: high.map((value, index) => (value + low[index] + close[index]) / 3) };
  if (title === "Median Price Transform") return { value: high.map((value, index) => (value + low[index]) / 2) };
  if (title === "Weighted Close") return { value: high.map((value, index) => (value + low[index] + 2 * close[index]) / 4) };
  if (title === "Average Price Transform") return { value: open.map((value, index) => (value + high[index] + low[index] + close[index]) / 4) };
  if (title === "Heikin-Ashi Transform") {
    const haClose = open.map((value, index) => (value + high[index] + low[index] + close[index]) / 4);
    const haOpen: NullableNumber[] = Array(close.length).fill(null);
    const haHigh: NullableNumber[] = Array(close.length).fill(null);
    const haLow: NullableNumber[] = Array(close.length).fill(null);
    for (let index = 0; index < close.length; index++) {
      haOpen[index] = index === 0 ? (open[index] + close[index]) / 2 : ((haOpen[index - 1] as number) + haClose[index - 1]) / 2;
      haHigh[index] = Math.max(high[index], haOpen[index] as number, haClose[index]);
      haLow[index] = Math.min(low[index], haOpen[index] as number, haClose[index]);
    }
    return { open: haOpen, high: haHigh, low: haLow, close: haClose };
  }
  if (title === "Log Price Transform") {
    if (close.some((value) => value <= 0)) throw new ContractError("log price requires positive close values");
    const logs = close.map(Math.log);
    return { log_price: logs, log_return: [null, ...logs.slice(1).map((value, index) => value - logs[index])] };
  }
  if (title === "Price Relative") {
    const benchmark = bars.map((bar) => bar.benchmark ?? null);
    if (benchmark.some((value) => value === null)) throw new ContractError("price relative requires benchmark on every bar");
    const base = numberParameter(parameters, "base", 100, { minimum: 0 });
    const initial = close[0] / (benchmark[0] as number);
    if (initial === 0) throw new ContractError("price relative initial ratio must be non-zero");
    return { value: close.map((price, index) => base * (price / (benchmark[index] as number)) / initial) };
  }
  if (title === "Normalized Price Transform") {
    const period = integer(parameters, "period", 20, 2);
    const mean = sma(close, period);
    const std = standardDeviation(close, period);
    return {
      value: close.map((price, index) => mean[index] === null || std[index] === null || std[index] === 0 ? null : (price - (mean[index] as number)) / (std[index] as number)),
      mean,
      std,
    };
  }
  throw new ContractError(`unsupported transform: ${title}`);
}

function rollingStatistics(title: string, bars: Bar[], parameters: Parameters): SeriesMap {
  const period = integer(parameters, "period", 20, 2);
  const close = bars.map((bar) => bar.close);
  if (title === "Rolling Percentile") {
    const tie = numberParameter(parameters, "tie_weight", 0.5, { minimum: 0, maximum: 1 });
    const output: NullableNumber[] = Array(close.length).fill(null);
    for (let end = period - 1; end < close.length; end++) {
      const window = close.slice(end - period + 1, end + 1);
      const current = window.at(-1) as number;
      output[end] = 100 * (window.filter((value) => value < current).length + tie * window.filter((value) => value === current).length) / window.length;
    }
    return { value: output };
  }
  if (title === "Rolling Quantile") {
    const q = numberParameter(parameters, "q", 0.5, { minimum: 0, maximum: 1 });
    return { value: rolling(close, period, (window) => quantile(window, q)) };
  }
  const asset = returns(close);
  const benchmarkValues = bars.map((bar) => bar.benchmark ?? null);
  if (benchmarkValues.some((value) => value === null)) throw new ContractError("rolling beta/alpha requires benchmark on every bar");
  const benchmark = returns(benchmarkValues as number[]);
  const beta: NullableNumber[] = Array(close.length).fill(null);
  const alpha: NullableNumber[] = Array(close.length).fill(null);
  for (let end = period; end < close.length; end++) {
    const x = benchmark.slice(end - period + 1, end + 1).filter((value): value is number => value !== null);
    const y = asset.slice(end - period + 1, end + 1).filter((value): value is number => value !== null);
    if (x.length !== period || y.length !== period) continue;
    const meanX = sum(x) / period;
    const meanY = sum(y) / period;
    const variance = sum(x.map((value) => (value - meanX) ** 2)) / period;
    if (variance === 0) continue;
    beta[end] = sum(x.map((value, index) => (value - meanX) * (y[index] - meanY))) / period / variance;
    alpha[end] = meanY - (beta[end] as number) * meanX;
  }
  return title === "Rolling Beta" ? { beta } : { alpha, beta };
}

function weighted(values: readonly number[], period: number, weights: readonly number[]): NullableNumber[] {
  const total = sum(weights);
  if (period !== weights.length || total === 0) throw new ContractError("invalid weighted-average configuration");
  return rolling(values, period, (window) => sum(window.map((value, index) => value * weights[index])) / total);
}

function change(values: readonly number[], lag = 1): NullableNumber[] {
  return values.map((value, index) => index < lag ? null : value - values[index - lag]);
}

function roc(values: readonly number[], lag: number): NullableNumber[] {
  return values.map((value, index) => index < lag || values[index - lag] === 0 ? null : value / values[index - lag] - 1);
}

function rollingExtreme(values: readonly number[], period: number, highest: boolean): NullableNumber[] {
  return rolling(values, period, (window) => highest ? Math.max(...window) : Math.min(...window));
}

function divide(numerator: readonly NullableNumber[], denominator: readonly NullableNumber[], scale = 1): NullableNumber[] {
  return numerator.map((value, index) => value === null || denominator[index] === null || denominator[index] === 0 ? null : scale * value / (denominator[index] as number));
}

function trendSmoothing(title: string, bars: Bar[], parameters: Parameters): SeriesMap {
  const close = bars.map((bar) => bar.close);
  const volume = bars.map((bar) => bar.volume);
  const period = integer(parameters, "period", 14, 2);
  if (title === "Triangular Moving Average (TRIMA)") {
    const first = Math.floor((period + 1) / 2);
    const second = Math.floor(period / 2) + 1;
    return { value: sma(sma(close, first), second) };
  }
  if (title === "Tillson T3 Moving Average") {
    const factor = numberParameter(parameters, "volume_factor", 0.7, { minimum: 0, maximum: 1 });
    const stages: NullableNumber[][] = [];
    let current: readonly NullableNumber[] = close;
    for (let stage = 0; stage < 6; stage++) {
      current = ema(current, period);
      stages.push(current as NullableNumber[]);
    }
    const [e3, e4, e5, e6] = stages.slice(2);
    return {
      value: e3.map((value, index) => {
        const row = [value, e4[index], e5[index], e6[index]];
        if (row.some((item) => item === null)) return null;
        return -(factor ** 3) * (row[3] as number)
          + (3 * factor ** 2 + 3 * factor ** 3) * (row[2] as number)
          + (-6 * factor ** 2 - 3 * factor - 3 * factor ** 3) * (row[1] as number)
          + (1 + 3 * factor + 3 * factor ** 2 + factor ** 3) * (row[0] as number);
      }),
    };
  }
  if (title === "Following Adaptive Moving Average (FAMA)") {
    const fast = numberParameter(parameters, "fast_alpha", 0.5, { minimum: 0, maximum: 1 });
    const slow = numberParameter(parameters, "slow_alpha", 0.05, { minimum: 0, maximum: 1 });
    const mama: NullableNumber[] = Array(close.length).fill(null);
    const fama: NullableNumber[] = Array(close.length).fill(null);
    for (let index = period; index < close.length; index++) {
      const direction = Math.abs(close[index] - close[index - period]);
      let noise = 0;
      for (let cursor = index - period + 1; cursor <= index; cursor++) noise += Math.abs(close[cursor] - close[cursor - 1]);
      const alpha = slow + (fast - slow) * (noise === 0 ? 0 : direction / noise);
      mama[index] = index === period ? close[index] : alpha * close[index] + (1 - alpha) * (mama[index - 1] as number);
      fama[index] = index === period ? mama[index] : alpha / 2 * (mama[index] as number) + (1 - alpha / 2) * (fama[index - 1] as number);
    }
    return { mama, fama };
  }
  if (title === "Arnaud Legoux Moving Average (ALMA)" || title === "Gaussian Moving Average") {
    const offset = numberParameter(parameters, "offset", title.startsWith("Arnaud") ? 0.85 : 0.5, { minimum: 0, maximum: 1 });
    const sigma = numberParameter(parameters, "sigma", 6, { minimum: 0.000001 });
    const center = offset * (period - 1);
    const width = period / sigma;
    const weights = Array.from({ length: period }, (_, index) => Math.exp(-((index - center) ** 2) / (2 * width ** 2)));
    return { value: weighted(close, period, weights) };
  }
  if (title === "Fractal Adaptive Moving Average (FRAMA)") {
    if (period % 2 !== 0) throw new ContractError("FRAMA period must be even");
    const minimumAlpha = numberParameter(parameters, "minimum_alpha", 0.01, { minimum: 0, maximum: 1 });
    const value: NullableNumber[] = Array(close.length).fill(null);
    const half = Math.floor(period / 2);
    for (let index = period - 1; index < close.length; index++) {
      const first = close.slice(index - period + 1, index - half + 1);
      const second = close.slice(index - half + 1, index + 1);
      const whole = close.slice(index - period + 1, index + 1);
      const n1 = (Math.max(...first) - Math.min(...first)) / half;
      const n2 = (Math.max(...second) - Math.min(...second)) / half;
      const n3 = (Math.max(...whole) - Math.min(...whole)) / period;
      const dimension = n1 + n2 <= 0 || n3 <= 0 ? 1 : (Math.log(n1 + n2) - Math.log(n3)) / Math.log(2);
      const alpha = Math.max(minimumAlpha, Math.min(1, Math.exp(-4.6 * (dimension - 1))));
      value[index] = index === period - 1 ? close[index] : alpha * close[index] + (1 - alpha) * (value[index - 1] as number);
    }
    return { value };
  }
  if (title === "Zero-Lag Exponential Moving Average (ZLEMA)") {
    const lag = Math.floor((period - 1) / 2);
    const adjusted = close.map((value, index) => index < lag ? null : value + value - close[index - lag]);
    return { value: ema(adjusted, period) };
  }
  if (title === "Least-Squares Moving Average (LSMA)") {
    return { value: rolling(close, period, (window) => {
      const [intercept, slope] = ols(window);
      return intercept + slope * (period - 1);
    }) };
  }
  if (title === "Variable Index Dynamic Average (VIDYA)") {
    const alpha = 2 / (period + 1);
    const momentum = change(close);
    const value: NullableNumber[] = Array(close.length).fill(null);
    for (let index = period; index < close.length; index++) {
      const window = momentum.slice(index - period + 1, index + 1);
      const gains = sum(window.map((item) => Math.max(item ?? 0, 0)));
      const losses = sum(window.map((item) => Math.max(-(item ?? 0), 0)));
      const cmo = gains + losses === 0 ? 0 : Math.abs((gains - losses) / (gains + losses));
      value[index] = index === period
        ? close[index]
        : alpha * cmo * close[index] + (1 - alpha * cmo) * (value[index - 1] as number);
    }
    return { value };
  }
  if (title === "McGinley Dynamic") {
    const k = numberParameter(parameters, "k", 0.6, { minimum: 0.000001 });
    const value: NullableNumber[] = Array(close.length).fill(null);
    value[0] = close[0];
    for (let index = 1; index < close.length; index++) {
      const previous = value[index - 1] as number;
      const ratio = previous ? close[index] / previous : 1;
      value[index] = previous + (close[index] - previous) / (k * period * ratio ** 4);
    }
    return { value };
  }
  if (title === "Jurik-Style Moving Average Design") {
    const base = numberParameter(parameters, "base_alpha", 2 / (period + 1), { minimum: 0, maximum: 1 });
    const sensitivity = numberParameter(parameters, "volatility_sensitivity", 0.5, { minimum: 0 });
    const minimumAlpha = numberParameter(parameters, "minimum_alpha", 0.01, { minimum: 0, maximum: 1 });
    const maximumAlpha = numberParameter(parameters, "maximum_alpha", 0.8, { minimum: 0, maximum: 1 });
    const changes = change(close).map((item) => Math.abs(item ?? 0));
    const baseline = sma(changes, period);
    const value: NullableNumber[] = Array(close.length).fill(null);
    const alphaSeries: NullableNumber[] = Array(close.length).fill(null);
    for (let index = 0; index < close.length; index++) {
      if (baseline[index] === null) continue;
      const z = baseline[index] === 0 ? 0 : changes[index] / (baseline[index] as number) - 1;
      const alpha = Math.max(minimumAlpha, Math.min(maximumAlpha, base * (1 + sensitivity * z)));
      alphaSeries[index] = alpha;
      value[index] = index === period - 1 ? close[index] : alpha * close[index] + (1 - alpha) * (value[index - 1] as number);
    }
    return { value, alpha: alphaSeries };
  }
  if (title === "Volume-Weighted Moving Average (VWMA)") {
    const value: NullableNumber[] = Array(close.length).fill(null);
    for (let index = period - 1; index < close.length; index++) {
      const prices = close.slice(index - period + 1, index + 1);
      const volumes = volume.slice(index - period + 1, index + 1);
      const total = sum(volumes);
      value[index] = total === 0 ? null : sum(prices.map((price, offset) => price * volumes[offset])) / total;
    }
    return { value };
  }
  if (title === "Quadratic-Weighted Moving Average") {
    return { value: weighted(close, period, Array.from({ length: period }, (_, index) => (index + 1) ** 2)) };
  }
  if (title === "Ehlers Super Smoother Filter") {
    const a1 = Math.exp(-Math.sqrt(2) * Math.PI / period);
    const b1 = 2 * a1 * Math.cos(Math.sqrt(2) * Math.PI / period);
    const c2 = b1;
    const c3 = -a1 * a1;
    const c1 = 1 - c2 - c3;
    const value: NullableNumber[] = Array(close.length).fill(null);
    for (let index = 0; index < close.length; index++) {
      value[index] = index < 2
        ? close[index]
        : c1 * (close[index] + close[index - 1]) / 2 + c2 * (value[index - 1] as number) + c3 * (value[index - 2] as number);
    }
    return { value };
  }
  if (title === "Ehlers Instantaneous Trendline") {
    const center = ema(close, Math.max(4, period));
    return { trendline: center, detrended: close.map((price, index) => center[index] === null ? null : price - (center[index] as number)) };
  }
  throw new ContractError(`unsupported trend smoother: ${title}`);
}

function directional(bars: Bar[], period: number): [NullableNumber[], NullableNumber[], NullableNumber[]] {
  const range = trueRange(bars);
  const plus: NullableNumber[] = [null];
  const minus: NullableNumber[] = [null];
  for (let index = 1; index < bars.length; index++) {
    const up = bars[index].high - bars[index - 1].high;
    const down = bars[index - 1].low - bars[index].low;
    plus.push(up > down && up > 0 ? up : 0);
    minus.push(down > up && down > 0 ? down : 0);
  }
  const averageRange = rma(range, period);
  const plusDi = divide(rma(plus, period), averageRange, 100);
  const minusDi = divide(rma(minus, period), averageRange, 100);
  const dx = plusDi.map((value, index) => value === null || minusDi[index] === null || value + (minusDi[index] as number) === 0
    ? null
    : 100 * Math.abs(value - (minusDi[index] as number)) / (value + (minusDi[index] as number)));
  return [plusDi, minusDi, rma(dx, period)];
}

function trendSystems(title: string, bars: Bar[], parameters: Parameters): SeriesMap {
  const period = integer(parameters, "period", 14, 2);
  const high = bars.map((bar) => bar.high);
  const low = bars.map((bar) => bar.low);
  const close = bars.map((bar) => bar.close);
  const open = bars.map((bar) => bar.open);
  const range = trueRange(bars);
  if (title === "Average Directional Index Rating (ADXR)") {
    const [plus, minus, adx] = directional(bars, period);
    const adxr = adx.map((value, index) => index < period || value === null || adx[index - period] === null
      ? null
      : (value + (adx[index - period] as number)) / 2);
    return { plus_di: plus, minus_di: minus, adx, adxr };
  }
  if (title.startsWith("Vortex Indicator")) {
    const plus: NullableNumber[] = [null, ...high.slice(1).map((value, index) => Math.abs(value - low[index]))];
    const minus: NullableNumber[] = [null, ...low.slice(1).map((value, index) => Math.abs(value - high[index]))];
    return { plus_vi: divide(rolling(plus, period, sum), rolling(range, period, sum)), minus_vi: divide(rolling(minus, period, sum), rolling(range, period, sum)) };
  }
  if (title === "Choppiness Index") {
    const total = rolling(range, period, sum);
    const highest = rollingExtreme(high, period, true);
    const lowest = rollingExtreme(low, period, false);
    return { value: total.map((value, index) => {
      const upper = highest[index];
      const lower = lowest[index];
      if (value === null || upper === null || lower === null || upper === lower || value <= 0) return null;
      return 100 * (Math.log(value / (upper - lower)) / Math.log(10)) / (Math.log(period) / Math.log(10));
    }) };
  }
  if (title === "Trend Intensity Index") {
    const mean = sma(close, period);
    const lookback = integer(parameters, "intensity_period", period, 2);
    const positive = close.map((value, index) => mean[index] === null ? null : Math.max(value - (mean[index] as number), 0));
    const negative = close.map((value, index) => mean[index] === null ? null : Math.max((mean[index] as number) - value, 0));
    const positiveTotal = rolling(positive, lookback, sum);
    const negativeTotal = rolling(negative, lookback, sum);
    return { value: positiveTotal.map((value, index) => value === null || negativeTotal[index] === null || value + (negativeTotal[index] as number) === 0
      ? null
      : 100 * value / (value + (negativeTotal[index] as number))) };
  }
  if (title === "QStick") return { value: sma(close.map((value, index) => value - open[index]), period) };
  if (title === "Mass Index") {
    const span = high.map((value, index) => value - low[index]);
    const first = ema(span, 9);
    return { value: rolling(divide(first, ema(first, 9)), integer(parameters, "sum_period", 25, 2), sum) };
  }
  if (title === "Vertical Horizontal Filter") {
    const highest = rollingExtreme(close, period, true);
    const lowest = rollingExtreme(close, period, false);
    const numerator = highest.map((value, index) => value === null || lowest[index] === null ? null : value - (lowest[index] as number));
    return { value: divide(numerator, rolling(change(close).map((value) => Math.abs(value ?? 0)), period, sum)) };
  }
  if (title === "Random Walk Index (High/Low)") {
    const randomHigh: NullableNumber[] = Array(close.length).fill(null);
    const randomLow: NullableNumber[] = Array(close.length).fill(null);
    for (let index = period; index < close.length; index++) {
      const highs: number[] = [];
      const lows: number[] = [];
      for (let length = 2; length <= period; length++) {
        const averageRange = sum((range.slice(index - length + 1, index + 1) as number[])) / length;
        if (averageRange) {
          highs.push((high[index] - low[index - length]) / (averageRange * Math.sqrt(length)));
          lows.push((high[index - length] - low[index]) / (averageRange * Math.sqrt(length)));
        }
      }
      randomHigh[index] = highs.length ? Math.max(...highs) : null;
      randomLow[index] = lows.length ? Math.max(...lows) : null;
    }
    return { high: randomHigh, low: randomLow };
  }
  if (title === "Trend Trigger Factor") {
    const value: NullableNumber[] = Array(close.length).fill(null);
    for (let index = 2 * period - 1; index < close.length; index++) {
      const currentHigh = Math.max(...high.slice(index - period + 1, index + 1));
      const currentLow = Math.min(...low.slice(index - period + 1, index + 1));
      const priorHigh = Math.max(...high.slice(index - 2 * period + 1, index - period + 1));
      const priorLow = Math.min(...low.slice(index - 2 * period + 1, index - period + 1));
      const buy = currentHigh - priorLow;
      const sell = priorHigh - currentLow;
      const denominator = 0.5 * (buy + sell);
      value[index] = denominator === 0 ? null : 100 * (buy - sell) / denominator;
    }
    return { value };
  }
  if (title === "Directional Trend Index") {
    const up: NullableNumber[] = [null, ...high.slice(1).map((value, index) => Math.max(value - high[index], 0))];
    const down: NullableNumber[] = [null, ...low.slice(1).map((value, index) => Math.max(low[index] - value, 0))];
    const difference = up.map((value, index) => value === null ? null : value - (down[index] as number));
    const total = up.map((value, index) => value === null ? null : value + (down[index] as number));
    return { value: divide(rma(difference, period), rma(total, period), 100) };
  }
  if (title === "Trend Strength Index") {
    const fast = integer(parameters, "fast_period", 7, 2);
    const slow = integer(parameters, "slow_period", 21, fast + 1);
    const fastAverage = ema(close, fast);
    const slowAverage = ema(close, slow);
    const spread = fastAverage.map((value, index) => value === null || slowAverage[index] === null ? null : Math.abs(value - (slowAverage[index] as number)));
    return { value: divide(spread, atr(bars, period)) };
  }
  throw new ContractError(`unsupported trend system: ${title}`);
}

function momentum(title: string, bars: Bar[], parameters: Parameters): SeriesMap {
  const close = bars.map((bar) => bar.close);
  const open = bars.map((bar) => bar.open);
  const high = bars.map((bar) => bar.high);
  const low = bars.map((bar) => bar.low);
  const period = integer(parameters, "period", 14, 2);
  const fast = integer(parameters, "fast_period", 5, 2);
  const slow = integer(parameters, "slow_period", 34, fast + 1);
  if (title === "Absolute Price Oscillator") {
    const fastAverage = ema(close, fast);
    const slowAverage = ema(close, slow);
    return { value: fastAverage.map((value, index) => value === null || slowAverage[index] === null ? null : value - (slowAverage[index] as number)) };
  }
  if (title === "Rate-of-Change Variants (ROC, ROCP, and ROCR)") {
    const rocp = roc(close, period);
    return { roc: rocp.map((value) => value === null ? null : 100 * value), rocp, rocr: rocp.map((value) => value === null ? null : 1 + value) };
  }
  if (title === "Price Momentum (MOM)") return { value: change(close, period) };
  if (title === "Chande Momentum Oscillator") {
    const difference = change(close);
    const gains = rolling(difference.map((value) => value === null ? null : Math.max(value, 0)), period, sum);
    const losses = rolling(difference.map((value) => value === null ? null : Math.max(-value, 0)), period, sum);
    return { value: gains.map((value, index) => value === null || losses[index] === null || value + (losses[index] as number) === 0
      ? null
      : 100 * (value - (losses[index] as number)) / (value + (losses[index] as number))) };
  }
  const medianPrice = high.map((value, index) => (value + low[index]) / 2);
  const averageFive = sma(medianPrice, 5);
  const averageThirtyFour = sma(medianPrice, 34);
  const awesome = averageFive.map((value, index) => value === null || averageThirtyFour[index] === null ? null : value - (averageThirtyFour[index] as number));
  if (title === "Awesome Oscillator") return { value: awesome };
  if (title === "Accelerator Oscillator") {
    const signal = sma(awesome, 5);
    return { value: awesome.map((value, index) => value === null || signal[index] === null ? null : value - (signal[index] as number)) };
  }
  if (title === "TRIX") {
    const triple = ema(ema(ema(close, period), period), period);
    return { value: triple.map((value, index) => index === 0 || value === null || triple[index - 1] === null || triple[index - 1] === 0
      ? null
      : 100 * (value / (triple[index - 1] as number) - 1)) };
  }
  if (title === "Stochastic Momentum Index") {
    const highest = rollingExtreme(high, period, true);
    const lowest = rollingExtreme(low, period, false);
    const distance = close.map((price, index) => highest[index] === null || lowest[index] === null ? null : price - ((highest[index] as number) + (lowest[index] as number)) / 2);
    const span = highest.map((value, index) => value === null || lowest[index] === null ? null : value - (lowest[index] as number));
    return { value: divide(ema(ema(distance, 3), 3), ema(ema(span, 3), 3), 200) };
  }
  if (title === "Relative Vigor Index") return { value: divide(sma(close.map((value, index) => value - open[index]), period), sma(high.map((value, index) => value - low[index]), period)) };
  if (title === "Relative Momentum Index") {
    const raw = change(close, integer(parameters, "momentum_lag", 5, 1));
    const up = rma(raw.map((value) => value === null ? null : Math.max(value, 0)), period);
    const down = rma(raw.map((value) => value === null ? null : Math.max(-value, 0)), period);
    return { value: up.map((value, index) => value === null || down[index] === null || value + (down[index] as number) === 0 ? null : 100 * value / (value + (down[index] as number))) };
  }
  if (title === "Fisher Transform") {
    const highest = rollingExtreme(close, period, true);
    const lowest = rollingExtreme(close, period, false);
    const normalized = close.map((value, index) => highest[index] === null || lowest[index] === null || highest[index] === lowest[index]
      ? null
      : Math.max(-0.999, Math.min(0.999, 2 * (value - (lowest[index] as number)) / ((highest[index] as number) - (lowest[index] as number)) - 1)));
    return { value: normalized.map((value) => value === null ? null : 0.5 * Math.log((1 + value) / (1 - value))) };
  }
  if (title === "Inverse Fisher Transform") {
    const scale = numberParameter(parameters, "source_scale", 0.1, { minimum: 0 });
    return { value: change(close).map((value) => {
      const transformed = scale * (value ?? 0);
      return (Math.exp(2 * transformed) - 1) / (Math.exp(2 * transformed) + 1);
    }) };
  }
  if (title === "Schaff Trend Cycle") {
    const emaTwelve = ema(close, 12);
    const emaTwentySix = ema(close, 26);
    const macd = emaTwelve.map((value, index) => value === null || emaTwentySix[index] === null ? null : value - (emaTwentySix[index] as number));
    const cycle = integer(parameters, "cycle_period", 10, 2);
    const stochastic = (values: NullableNumber[]): NullableNumber[] => {
      const output: NullableNumber[] = Array(values.length).fill(null);
      for (let index = cycle - 1; index < values.length; index++) {
        const window = values.slice(index - cycle + 1, index + 1);
        if (window.every((value) => value !== null)) {
          const numeric = window as number[];
          const lower = Math.min(...numeric);
          const upper = Math.max(...numeric);
          output[index] = upper === lower ? 0 : 100 * ((values[index] as number) - lower) / (upper - lower);
        }
      }
      return output;
    };
    return { value: ema(stochastic(ema(stochastic(macd), 3)), 3) };
  }
  if (title === "Quantitative Qualitative Estimation (QQE)") {
    const difference = change(close);
    const gain = rma(difference.map((value) => value === null ? null : Math.max(value, 0)), period);
    const loss = rma(difference.map((value) => value === null ? null : Math.max(-value, 0)), period);
    const rsi = gain.map((value, index) => value === null || loss[index] === null ? null : value + (loss[index] as number) === 0 ? 50 : 100 * value / (value + (loss[index] as number)));
    const smooth = ema(rsi, 5);
    const delta = smooth.map((value, index) => index === 0 || value === null || smooth[index - 1] === null ? null : Math.abs(value - (smooth[index - 1] as number)));
    const band = rma(rma(delta, period), period);
    const factor = numberParameter(parameters, "factor", 4.236, { minimum: 0 });
    return {
      rsi: smooth,
      upper: smooth.map((value, index) => value === null || band[index] === null ? null : value + factor * (band[index] as number)),
      lower: smooth.map((value, index) => value === null || band[index] === null ? null : value - factor * (band[index] as number)),
    };
  }
  if (title === "WaveTrend Oscillator") {
    const averagePrice = high.map((value, index) => (value + low[index] + close[index]) / 3);
    const esa = ema(averagePrice, 10);
    const deviation = ema(averagePrice.map((value, index) => esa[index] === null ? null : Math.abs(value - (esa[index] as number))), 10);
    const channelIndex = averagePrice.map((value, index) => esa[index] === null || deviation[index] === null || deviation[index] === 0 ? null : (value - (esa[index] as number)) / (0.015 * (deviation[index] as number)));
    const wt1 = ema(channelIndex, 21);
    return { wt1, wt2: sma(wt1, 4) };
  }
  if (title === "Know Sure Thing (KST)") {
    const specs = [[10, 10, 1], [15, 10, 2], [20, 10, 3], [30, 15, 4]] as const;
    const components = specs.map(([lag, smooth]) => sma(roc(close, lag).map((value) => value === null ? null : 100 * value), smooth));
    const kst = close.map((_, index) => components.some((component) => component[index] === null)
      ? null
      : sum(components.map((component, offset) => specs[offset][2] * (component[index] as number))));
    return { kst, signal: sma(kst, 9) };
  }
  if (title === "Chande Forecast Oscillator") {
    const forecast = rolling(close, period, (window) => {
      const [intercept, slope] = ols(window);
      return intercept + slope * (period - 1);
    });
    return { value: close.map((price, index) => forecast[index] === null || price === 0 ? null : 100 * (price - (forecast[index] as number)) / price) };
  }
  if (title === "Detrended Price Oscillator") {
    const mean = sma(close, period);
    const shift = Math.floor(period / 2) + 1;
    return { value: close.map((_, index) => index < shift || mean[index] === null ? null : close[index - shift] - (mean[index] as number)) };
  }
  if (title === "Balance of Power") return { value: close.map((value, index) => high[index] === low[index] ? null : (value - open[index]) / (high[index] - low[index])) };
  if (title === "Psychological Line") {
    const up: NullableNumber[] = [null, ...close.slice(1).map((value, index) => value > close[index] ? 1 : 0)];
    return { value: rolling(up, period, sum).map((value) => value === null ? null : 100 * value / period) };
  }
  if (title === "Pretty Good Oscillator") {
    const mean = sma(close, period);
    return { value: divide(close.map((price, index) => mean[index] === null ? null : price - (mean[index] as number)), atr(bars, period)) };
  }
  if (title === "Price Momentum Oscillator") {
    const raw = roc(close, 1).map((value) => value === null ? null : 1000 * value);
    const pmo = ema(ema(raw, 10), 14);
    return { pmo, signal: ema(pmo, 9) };
  }
  throw new ContractError(`unsupported momentum indicator: ${title}`);
}

function vwma(values: readonly number[], volume: readonly number[], period: number): NullableNumber[] {
  const output: NullableNumber[] = Array(values.length).fill(null);
  for (let index = period - 1; index < values.length; index++) {
    const weights = volume.slice(index - period + 1, index + 1);
    const total = sum(weights);
    output[index] = total === 0 ? null : sum(values.slice(index - period + 1, index + 1).map((value, offset) => value * weights[offset])) / total;
  }
  return output;
}

function volumeIndicators(title: string, bars: Bar[], parameters: Parameters): SeriesMap {
  const close = bars.map((bar) => bar.close);
  const high = bars.map((bar) => bar.high);
  const low = bars.map((bar) => bar.low);
  const volume = bars.map((bar) => bar.volume);
  const typical = high.map((value, index) => (value + low[index] + close[index]) / 3);
  const period = integer(parameters, "period", 14, 2);
  const fast = integer(parameters, "fast_period", 3, 2);
  const slow = integer(parameters, "slow_period", 10, fast + 1);
  const multiplier = high.map((value, index) => value === low[index] ? 0 : ((close[index] - low[index]) - (value - close[index])) / (value - low[index]));
  const flowVolume = multiplier.map((value, index) => value * volume[index]);
  const accumulation: number[] = [];
  let running = 0;
  for (const value of flowVolume) {
    running += value;
    accumulation.push(running);
  }
  if (title === "Chaikin A/D Oscillator") {
    const fastAverage = ema(accumulation, fast);
    const slowAverage = ema(accumulation, slow);
    return { ad: accumulation, value: fastAverage.map((value, index) => value === null || slowAverage[index] === null ? null : value - (slowAverage[index] as number)) };
  }
  if (title === "Session VWAP Indicator" || title === "Anchored VWAP") {
    const anchor = title.startsWith("Anchored") ? integer(parameters, "anchor_index", 0, 0) : 0;
    const value: NullableNumber[] = Array(close.length).fill(null);
    let priceVolume = 0;
    let totalVolume = 0;
    let previousSession: string | null = null;
    for (let index = 0; index < bars.length; index++) {
      const session = bars[index].timestamp.slice(0, 10);
      if (title.startsWith("Session") && session !== previousSession) {
        priceVolume = 0;
        totalVolume = 0;
      }
      previousSession = session;
      if (index < anchor) continue;
      priceVolume += typical[index] * volume[index];
      totalVolume += volume[index];
      value[index] = totalVolume === 0 ? null : priceVolume / totalVolume;
    }
    return { value };
  }
  if (title === "Negative Volume Index" || title === "Positive Volume Index") {
    const value = [1000];
    for (let index = 1; index < close.length; index++) {
      const active = title.startsWith("Negative") ? volume[index] < volume[index - 1] : volume[index] > volume[index - 1];
      value.push(active && close[index - 1] !== 0 ? value.at(-1)! * close[index] / close[index - 1] : value.at(-1)!);
    }
    return { value };
  }
  if (title === "Ease of Movement") {
    const raw: NullableNumber[] = [null];
    const scale = numberParameter(parameters, "volume_scale", 1_000_000, { minimum: 0.000001 });
    for (let index = 1; index < close.length; index++) {
      const box = high[index] === low[index] ? 0 : (volume[index] / scale) / (high[index] - low[index]);
      raw.push(box === 0 ? null : (typical[index] - typical[index - 1]) / box);
    }
    return { raw, value: sma(raw, period) };
  }
  if (title === "Klinger Volume Oscillator") {
    const trend = [1];
    for (let index = 1; index < close.length; index++) {
      trend.push(high[index] + low[index] + close[index] > high[index - 1] + low[index - 1] + close[index - 1] ? 1 : -1);
    }
    const force = trend.map((value, index) => high[index] === low[index] ? 0 : value * volume[index] * Math.abs(2 * (close[index] - low[index]) / (high[index] - low[index]) - 1));
    const fastKlinger = integer(parameters, "fast_period", 34, 2);
    const slowKlinger = integer(parameters, "slow_period", 55, fastKlinger + 1);
    const fastAverage = ema(force, fastKlinger);
    const slowAverage = ema(force, slowKlinger);
    return { value: fastAverage.map((value, index) => value === null || slowAverage[index] === null ? null : value - (slowAverage[index] as number)) };
  }
  if (title === "Volume Oscillator") {
    const fastAverage = sma(volume, fast);
    const slowAverage = sma(volume, slow);
    return { value: fastAverage.map((value, index) => value === null || slowAverage[index] === null ? null : value - (slowAverage[index] as number)) };
  }
  if (title === "Percentage Volume Oscillator") {
    const fastAverage = ema(volume, fast);
    const slowAverage = ema(volume, slow);
    return { value: divide(fastAverage.map((value, index) => value === null || slowAverage[index] === null ? null : value - (slowAverage[index] as number)), slowAverage, 100) };
  }
  if (title === "Volume Rate of Change") return { value: roc(volume, period).map((value) => value === null ? null : 100 * value) };
  if (title === "Relative Volume") return { value: divide(volume, sma(volume, period)) };
  if (title === "Money Flow Multiplier and Money Flow Volume") return { mfm: multiplier, mfv: flowVolume };
  if (title === "Volume-Weighted MACD") {
    const fastAverage = vwma(close, volume, fast);
    const slowAverage = vwma(close, volume, slow);
    const line = fastAverage.map((value, index) => value === null || slowAverage[index] === null ? null : value - (slowAverage[index] as number));
    return { value: line, signal: ema(line, integer(parameters, "signal_period", 9, 2)) };
  }
  if (title === "Volume Zone Oscillator") {
    const signed = [0, ...close.slice(1).map((value, index) => (value > close[index] ? 1 : value < close[index] ? -1 : 0) * volume[index + 1])];
    return { value: divide(ema(signed, period), ema(volume, period), 100) };
  }
  if (title === "Twiggs Money Flow") {
    const flow = [0];
    for (let index = 1; index < close.length; index++) {
      const top = Math.max(high[index], close[index - 1]);
      const bottom = Math.min(low[index], close[index - 1]);
      flow.push(top === bottom ? 0 : volume[index] * ((close[index] - bottom) - (top - close[index])) / (top - bottom));
    }
    return { value: divide(ema(flow, period), ema(volume, period)) };
  }
  throw new ContractError(`unsupported volume indicator: ${title}`);
}

function volatility(title: string, bars: Bar[], parameters: Parameters): SeriesMap {
  const close = bars.map((bar) => bar.close);
  const open = bars.map((bar) => bar.open);
  const high = bars.map((bar) => bar.high);
  const low = bars.map((bar) => bar.low);
  const period = integer(parameters, "period", 14, 2);
  const range = trueRange(bars);
  const averageRange = atr(bars, period);
  if (title === "Normalized ATR and ATR Percentage") return { atr: averageRange, natr: divide(averageRange, close, 100) };
  if (title === "Chaikin Volatility") {
    const smooth = ema(high.map((value, index) => value - low[index]), period);
    const lag = integer(parameters, "roc_period", 10, 1);
    return { value: smooth.map((value, index) => index < lag || value === null || smooth[index - lag] === null || smooth[index - lag] === 0
      ? null
      : 100 * (value / (smooth[index - lag] as number) - 1)) };
  }
  if (title === "Ulcer Index") {
    const peak: number[] = [];
    let running = -Infinity;
    for (const value of close) {
      running = Math.max(running, value);
      peak.push(running);
    }
    const drawdown = close.map((value, index) => 100 * (value / peak[index] - 1));
    return { value: rolling(drawdown, period, (window) => Math.sqrt(sum(window.map((value) => value ** 2)) / window.length)) };
  }
  if (title === "Relative Volatility Index") {
    const deviation = standardDeviation(close, period);
    const up = deviation.map((value, index) => index === 0 || value === null ? null : close[index] > close[index - 1] ? value : 0);
    const down = deviation.map((value, index) => index === 0 || value === null ? null : close[index] < close[index - 1] ? value : 0);
    const positive = rma(up, period);
    const negative = rma(down, period);
    return { value: positive.map((value, index) => value === null || negative[index] === null || value + (negative[index] as number) === 0 ? null : 100 * value / (value + (negative[index] as number))) };
  }
  if (title === "Volatility Ratio") {
    const short = integer(parameters, "short_period", 5, 2);
    const long = integer(parameters, "long_period", 20, short + 1);
    const changes = returns(close);
    return { value: divide(standardDeviation(changes, short), standardDeviation(changes, long)) };
  }
  if (title === "Volatility Quality Index") {
    const signed = [0, ...close.slice(1).map((value, index) => (value > close[index] ? 1 : value < close[index] ? -1 : 0) * (range[index + 1] as number))];
    const cumulative: number[] = [];
    let total = 0;
    for (const value of signed) {
      total += value;
      cumulative.push(total);
    }
    return { raw: signed, value: ema(cumulative, period) };
  }
  if (title === "Average Daily Range") return { value: sma(high.map((value, index) => value - low[index]), period) };
  if (title === "Gap Volatility") {
    const gap: NullableNumber[] = [null, ...open.slice(1).map((value, index) => value - close[index])];
    return { gap, value: standardDeviation(gap, period) };
  }
  if (title === "Range Efficiency Ratio") {
    const direction = close.map((value, index) => index < period ? null : Math.abs(value - close[index - period]));
    return { value: divide(direction, rolling(high.map((value, index) => value - low[index]), period, sum)) };
  }
  if (title === "High-Low Range Percentage") return { value: high.map((value, index) => value + low[index] === 0 ? null : 200 * (value - low[index]) / (value + low[index])) };
  if (title === "Normalized Price Range") {
    const highest = rollingExtreme(high, period, true);
    const lowest = rollingExtreme(low, period, false);
    return { value: close.map((value, index) => highest[index] === null || lowest[index] === null || highest[index] === lowest[index] ? null : (value - (lowest[index] as number)) / ((highest[index] as number) - (lowest[index] as number))) };
  }
  if (title === "Volatility Stop") {
    const multiplier = numberParameter(parameters, "multiplier", 3, { minimum: 0 });
    const highest = rollingExtreme(close, period, true);
    const lowest = rollingExtreme(close, period, false);
    return {
      long_stop: highest.map((value, index) => value === null || averageRange[index] === null ? null : value - multiplier * (averageRange[index] as number)),
      short_stop: lowest.map((value, index) => value === null || averageRange[index] === null ? null : value + multiplier * (averageRange[index] as number)),
    };
  }
  throw new ContractError(`unsupported volatility indicator: ${title}`);
}

function bands(title: string, bars: Bar[], parameters: Parameters): SeriesMap {
  const close = bars.map((bar) => bar.close);
  const high = bars.map((bar) => bar.high);
  const low = bars.map((bar) => bar.low);
  const period = integer(parameters, "period", 20, 2);
  const multiplier = numberParameter(parameters, "multiplier", 2, { minimum: 0 });
  const center = sma(close, period);
  const deviation = standardDeviation(close, period);
  const averageRange = atr(bars, period);
  const bundle = (middle: NullableNumber[], width: NullableNumber[]): SeriesMap => ({
    center: middle,
    upper: middle.map((value, index) => value === null || width[index] === null ? null : value + multiplier * (width[index] as number)),
    lower: middle.map((value, index) => value === null || width[index] === null ? null : value - multiplier * (width[index] as number)),
  });
  if (title === "Bollinger %B") {
    // Reuse the already-shipping Bollinger Bands implementation; only adapt its
    // established series names to this topic's frozen object contract.
    const shared = multiplier === 0 ? bundle(center, deviation) : bollingerBands(close, period, multiplier);
    const upper = shared.upper as NullableNumber[];
    const lower = shared.lower as NullableNumber[];
    return {
      center: multiplier === 0 ? center : shared.middle as NullableNumber[],
      upper,
      lower,
      percent_b: close.map((value, index) => upper[index] === null || lower[index] === null || upper[index] === lower[index] ? null : (value - (lower[index] as number)) / ((upper[index] as number) - (lower[index] as number))),
    };
  }
  if (title === "Standard Deviation Channel") return bundle(center, deviation);
  if (title === "Moving Average Envelope") {
    const percentage = numberParameter(parameters, "percentage", 0.025, { minimum: 0 });
    return {
      center,
      upper: center.map((value) => value === null ? null : value * (1 + percentage)),
      lower: center.map((value) => value === null ? null : value * (1 - percentage)),
    };
  }
  // ATR Bands and STARC Bands intentionally freeze the same arithmetic.
  if (title === "ATR Bands" || title === "STARC Bands") return bundle(center, averageRange);
  if (title === "Regression Channel" || title === "Raff Regression Channel") {
    const middle: NullableNumber[] = Array(close.length).fill(null);
    const width: NullableNumber[] = Array(close.length).fill(null);
    for (let index = period - 1; index < close.length; index++) {
      const window = close.slice(index - period + 1, index + 1);
      const [, , fitted] = ols(window);
      middle[index] = fitted.at(-1)!;
      const residual = window.map((value, offset) => value - fitted[offset]);
      width[index] = title.startsWith("Raff") ? Math.max(...residual.map(Math.abs)) : Math.sqrt(sum(residual.map((value) => value ** 2)) / period);
    }
    return bundle(middle, width);
  }
  if (title === "Fractal Chaos Bands") {
    const upper: NullableNumber[] = Array(close.length).fill(null);
    const lower: NullableNumber[] = Array(close.length).fill(null);
    let upperHold: number | null = null;
    let lowerHold: number | null = null;
    for (let index = 0; index < close.length; index++) {
      if (index >= 4) {
        const pivot = index - 2;
        if (high[pivot] === Math.max(...high.slice(pivot - 2, pivot + 3))) upperHold = high[pivot];
        if (low[pivot] === Math.min(...low.slice(pivot - 2, pivot + 3))) lowerHold = low[pivot];
      }
      upper[index] = upperHold;
      lower[index] = lowerHold;
    }
    return { upper, lower };
  }
  if (title === "Projection Bands") {
    const upper: NullableNumber[] = Array(close.length).fill(null);
    const lowerBand: NullableNumber[] = Array(close.length).fill(null);
    for (let index = period - 1; index < close.length; index++) {
      const highWindow = high.slice(index - period + 1, index + 1);
      const lowWindow = low.slice(index - period + 1, index + 1);
      const [, highSlope] = ols(highWindow);
      const [, lowSlope] = ols(lowWindow);
      upper[index] = Math.max(...highWindow.map((value, offset) => value + highSlope * (period - 1 - offset)));
      lowerBand[index] = Math.min(...lowWindow.map((value, offset) => value + lowSlope * (period - 1 - offset)));
    }
    return { upper, lower: lowerBand };
  }
  if (title === "Dynamic Zone Bands") {
    const q = numberParameter(parameters, "q", 0.2, { minimum: 0, maximum: 0.5 });
    return { upper: rolling(close, period, (window) => quantile(window, 1 - q)), lower: rolling(close, period, (window) => quantile(window, q)), center };
  }
  if (title === "TTM Squeeze" || title === "Squeeze Momentum") {
    const bollinger = bundle(center, deviation);
    const exponential = ema(close, period);
    const keltner = bundle(exponential, averageRange);
    const squeeze = close.map((_, index) => {
      const row = [bollinger.upper[index], keltner.upper[index], bollinger.lower[index], keltner.lower[index]];
      return row.some((value) => value === null) ? null : (row[0] as number) < (row[1] as number) && (row[2] as number) > (row[3] as number);
    });
    const result: SeriesMap = {
      squeeze_on: squeeze,
      bb_upper: bollinger.upper,
      bb_lower: bollinger.lower,
      kc_upper: keltner.upper,
      kc_lower: keltner.lower,
    };
    if (title === "Squeeze Momentum") {
      const highest = rollingExtreme(high, period, true);
      const lowest = rollingExtreme(low, period, false);
      const displacement = close.map((value, index) => highest[index] === null || lowest[index] === null ? null : value - ((highest[index] as number) + (lowest[index] as number)) / 2);
      result.momentum = rolling(displacement, period, (window) => ols(window)[1]);
    }
    return result;
  }
  if (title === "Adaptive Price Zone") {
    const middle = ema(ema(close, period), period);
    const width = ema(ema(high.map((value, index) => value - low[index]), period), period);
    return bundle(middle, width);
  }
  throw new ContractError(`unsupported band indicator: ${title}`);
}

function levels(title: string, bars: Bar[], parameters: Parameters): SeriesMap {
  const high = bars.map((bar) => bar.high);
  const low = bars.map((bar) => bar.low);
  const close = bars.map((bar) => bar.close);
  const open = bars.map((bar) => bar.open);
  const count = close.length;
  const period = integer(parameters, "period", 20, 2);
  const pivotTitles = [
    "Classic and Floor-Trader Pivot Points",
    "Fibonacci Pivot Points",
    "Camarilla Pivot Points",
    "Woodie Pivot Points",
    "DeMark Pivot Points",
    "Pivot Range Width",
  ];
  if (pivotTitles.includes(title)) {
    const keys = ["pivot", "r1", "s1", "r2", "s2"] as const;
    let output: SeriesMap = Object.fromEntries(keys.map((key) => [key, Array(count).fill(null)]));
    if (title === "Pivot Range Width") {
      output = { pivot: Array(count).fill(null), bottom: Array(count).fill(null), top: Array(count).fill(null), width: Array(count).fill(null) };
    }
    for (let index = 1; index < count; index++) {
      const previousHigh = high[index - 1];
      const previousLow = low[index - 1];
      const previousClose = close[index - 1];
      const previousOpen = open[index - 1];
      const span = previousHigh - previousLow;
      let pivot: number;
      let values: Array<number | null>;
      if (title.startsWith("Classic")) {
        pivot = (previousHigh + previousLow + previousClose) / 3;
        values = [2 * pivot - previousLow, 2 * pivot - previousHigh, pivot + span, pivot - span];
      } else if (title.startsWith("Fibonacci")) {
        pivot = (previousHigh + previousLow + previousClose) / 3;
        values = [pivot + 0.382 * span, pivot - 0.382 * span, pivot + 0.618 * span, pivot - 0.618 * span];
      } else if (title.startsWith("Camarilla")) {
        pivot = (previousHigh + previousLow + previousClose) / 3;
        values = [previousClose + 1.1 * span / 12, previousClose - 1.1 * span / 12, previousClose + 1.1 * span / 6, previousClose - 1.1 * span / 6];
      } else if (title.startsWith("Woodie")) {
        pivot = (previousHigh + previousLow + 2 * open[index]) / 4;
        values = [2 * pivot - previousLow, 2 * pivot - previousHigh, pivot + span, pivot - span];
      } else if (title.startsWith("DeMark")) {
        const x = previousClose < previousOpen
          ? previousHigh + 2 * previousLow + previousClose
          : previousClose > previousOpen
          ? 2 * previousHigh + previousLow + previousClose
          : previousHigh + previousLow + 2 * previousClose;
        pivot = x / 4;
        values = [x / 2 - previousLow, x / 2 - previousHigh, null, null];
      } else {
        pivot = (previousHigh + previousLow + previousClose) / 3;
        const bottom = (previousHigh + previousLow) / 2;
        const top = 2 * pivot - bottom;
        output.pivot[index] = pivot;
        output.bottom[index] = bottom;
        output.top[index] = top;
        output.width[index] = Math.abs(top - bottom);
        continue;
      }
      output.pivot[index] = pivot;
      keys.slice(1).forEach((key, offset) => { output[key][index] = values[offset]; });
    }
    return output;
  }
  if (title === "Rolling Support and Resistance") {
    const support: NullableNumber[] = Array(count).fill(null);
    const resistance: NullableNumber[] = Array(count).fill(null);
    for (let index = period; index < count; index++) {
      support[index] = Math.min(...low.slice(index - period, index));
      resistance[index] = Math.max(...high.slice(index - period, index));
    }
    return { support, resistance };
  }
  // Fractal support/resistance is deliberately the same causal five-bar
  // confirmation used by Fractal Chaos Bands.
  if (title === "Fractal Support and Resistance") return bands("Fractal Chaos Bands", bars, parameters);
  if (title === "ATR Support and Resistance") {
    const center = sma(close, period);
    const averageRange = atr(bars, period);
    const multiplier = numberParameter(parameters, "multiplier", 2, { minimum: 0 });
    return {
      center,
      support: center.map((value, index) => value === null || averageRange[index] === null ? null : value - multiplier * (averageRange[index] as number)),
      resistance: center.map((value, index) => value === null || averageRange[index] === null ? null : value + multiplier * (averageRange[index] as number)),
    };
  }
  throw new ContractError(`unsupported level system: ${title}`);
}

function regime(title: string, bars: Bar[], parameters: Parameters): SeriesMap {
  const high = bars.map((bar) => bar.high);
  const low = bars.map((bar) => bar.low);
  const close = bars.map((bar) => bar.close);
  const count = close.length;
  const period = integer(parameters, "period", 20, 2);
  const averageRange = atr(bars, period);
  const highest = rollingExtreme(high, period, true);
  const lowest = rollingExtreme(low, period, false);
  if (title === "Highest-High and Lowest-Low Primitives") return { highest, lowest };
  if (title === "Single-Asset New-High/New-Low Signal" || title === "Donchian Breakout" || title === "Breakout Strength") {
    const upper: NullableNumber[] = Array(count).fill(null);
    const lower: NullableNumber[] = Array(count).fill(null);
    for (let index = period; index < count; index++) {
      upper[index] = Math.max(...high.slice(index - period, index));
      lower[index] = Math.min(...low.slice(index - period, index));
    }
    const newHigh = upper.map((value, index) => value === null ? null : close[index] > value);
    const newLow = lower.map((value, index) => value === null ? null : close[index] < value);
    if (title === "Breakout Strength") {
      return {
        up_strength: upper.map((value, index) => value === null || averageRange[index] === null || averageRange[index] === 0 ? null : (close[index] - value) / (averageRange[index] as number)),
        down_strength: lower.map((value, index) => value === null || averageRange[index] === null || averageRange[index] === 0 ? null : (value - close[index]) / (averageRange[index] as number)),
      };
    }
    return { upper, lower, new_high: newHigh, new_low: newLow };
  }
  if (title === "Opening Range Breakout") {
    const opening = integer(parameters, "opening_bars", 5, 1);
    const upper: NullableNumber[] = Array(count).fill(null);
    const lower: NullableNumber[] = Array(count).fill(null);
    const upBreak: Array<boolean | null> = Array(count).fill(null);
    const downBreak: Array<boolean | null> = Array(count).fill(null);
    for (let index = opening; index < count; index++) {
      upper[index] = Math.max(...high.slice(0, opening));
      lower[index] = Math.min(...low.slice(0, opening));
      upBreak[index] = close[index] > (upper[index] as number);
      downBreak[index] = close[index] < (lower[index] as number);
    }
    return { upper, lower, up_break: upBreak, down_break: downBreak };
  }
  if (title === "Price Compression Index") {
    return { value: divide(atr(bars, integer(parameters, "short_period", 5, 2)), atr(bars, integer(parameters, "long_period", 20, 6)), 100) };
  }
  const rawChange = change(close);
  const absoluteChange = rawChange.map((value) => value === null ? null : Math.abs(value));
  if (title === "Range Expansion Index") return { value: divide(rolling(rawChange, period, sum), rolling(absoluteChange, period, sum), 100) };
  if (title === "Fractal Dimension Index") {
    const value: NullableNumber[] = Array(count).fill(null);
    for (let index = period; index < count; index++) {
      const window = close.slice(index - period, index + 1);
      let path = 0;
      for (let offset = 1; offset < window.length; offset++) path += Math.abs(window[offset] - window[offset - 1]);
      const span = Math.max(...window) - Math.min(...window);
      value[index] = path === 0 || span === 0 ? 1 : Math.max(1, Math.min(2, 1 + (Math.log(path) - Math.log(span)) / Math.log(period)));
    }
    return { value };
  }
  if (title === "Hurst Exponent") {
    const value: NullableNumber[] = Array(count).fill(null);
    for (let index = period - 1; index < count; index++) {
      const window = close.slice(index - period + 1, index + 1);
      const mean = sum(window) / period;
      const cumulative: number[] = [];
      let total = 0;
      for (const observation of window) {
        total += observation - mean;
        cumulative.push(total);
      }
      const range = Math.max(...cumulative) - Math.min(...cumulative);
      const deviation = Math.sqrt(sum(window.map((observation) => (observation - mean) ** 2)) / period);
      value[index] = range === 0 || deviation === 0 ? null : Math.log(range / deviation) / Math.log(period);
    }
    return { value };
  }
  const direction = close.map((value, index) => index < period ? null : Math.abs(value - close[index - period]));
  const efficiency = divide(direction, rolling(absoluteChange, period, sum));
  if (title === "Efficiency Ratio") return { value: efficiency };
  if (title === "Market Meanness Index") {
    const value: NullableNumber[] = Array(count).fill(null);
    for (let index = period - 1; index < count; index++) {
      const window = close.slice(index - period + 1, index + 1);
      const center = median(window);
      let crossings = 0;
      for (let offset = 1; offset < window.length; offset++) {
        if ((window[offset] - center) * (window[offset - 1] - center) < 0) crossings++;
      }
      value[index] = 100 * crossings / (period - 1);
    }
    return { value };
  }
  if (title === "Trend/Range Regime Classifier") {
    // This dependency is intentional: one choppiness implementation defines
    // both its own topic and the regime classifier's threshold input.
    const choppiness = trendSystems("Choppiness Index", bars, { period }).value as NullableNumber[];
    const labels = efficiency.map((value, index) => value === null || choppiness[index] === null
      ? null
      : value >= 0.55 && (choppiness[index] as number) <= 45
      ? "trend"
      : value <= 0.25 && (choppiness[index] as number) >= 55
      ? "range"
      : "uncertain");
    return { efficiency, choppiness, regime: labels };
  }
  if (title === "Volatility Regime Classifier") {
    const realized = standardDeviation(returns(close), period);
    const lookback = integer(parameters, "rank_period", 40, period);
    const labels: Array<string | null> = Array(count).fill(null);
    for (let index = lookback - 1; index < count; index++) {
      const window = realized.slice(index - lookback + 1, index + 1);
      if (window.every((value) => value !== null)) {
        const rank = (window as number[]).filter((value) => value <= (realized[index] as number)).length / lookback;
        labels[index] = rank <= 0.25 ? "low" : rank >= 0.75 ? "high" : "normal";
      }
    }
    return { volatility: realized, regime: labels };
  }
  if (title === "Directional Persistence") {
    const signs: NullableNumber[] = [null, ...rawChange.slice(1).map((value) => (value as number) > 0 ? 1 : (value as number) < 0 ? -1 : 0)];
    return { value: rolling(signs, period, sum).map((value) => value === null ? null : Math.abs(value) / period) };
  }
  // Swing Structure Detector and Higher-High/Lower-Low Structure intentionally
  // share this byte-identical state transition.
  if (title === "Swing Structure Detector" || title === "Higher-High/Lower-Low Structure") {
    const swingHigh: NullableNumber[] = Array(count).fill(null);
    const swingLow: NullableNumber[] = Array(count).fill(null);
    const label: Array<string | null> = Array(count).fill(null);
    let lastHigh: number | null = null;
    let lastLow: number | null = null;
    for (let index = 4; index < count; index++) {
      label[index] = "none";
      const pivot = index - 2;
      if (high[pivot] === Math.max(...high.slice(pivot - 2, pivot + 3))) {
        swingHigh[index] = high[pivot];
        label[index] = lastHigh !== null ? high[pivot] > lastHigh ? "HH" : "LH" : "swing-high";
        lastHigh = high[pivot];
      }
      if (low[pivot] === Math.min(...low.slice(pivot - 2, pivot + 3))) {
        swingLow[index] = low[pivot];
        label[index] = lastLow !== null ? low[pivot] > lastLow ? "HL" : "LL" : "swing-low";
        lastLow = low[pivot];
      }
    }
    return { swing_high: swingHigh, swing_low: swingLow, structure: label };
  }
  if (title === "Inside/Outside Bar Structure") {
    const label: Array<string | null> = [null];
    for (let index = 1; index < count; index++) {
      label.push(high[index] <= high[index - 1] && low[index] >= low[index - 1]
        ? "inside"
        : high[index] >= high[index - 1] && low[index] <= low[index - 1]
        ? "outside"
        : "neither");
    }
    return { structure: label };
  }
  if (title === "Market Entropy") {
    const states: NullableNumber[] = [null, ...rawChange.slice(1).map((value) => (value as number) > 0 ? 1 : (value as number) < 0 ? -1 : 0)];
    const value: NullableNumber[] = Array(count).fill(null);
    for (let index = period; index < count; index++) {
      const window = states.slice(index - period + 1, index + 1);
      const counts = [-1, 0, 1].map((state) => window.filter((value) => value === state).length);
      const probabilities = counts.filter(Boolean).map((observations) => observations / period);
      value[index] = -sum(probabilities.map((probability) => probability * Math.log(probability))) / Math.log(3);
    }
    return { value };
  }
  throw new ContractError(`unsupported regime topic: ${title}`);
}

function cycles(title: string, bars: Bar[], parameters: Parameters): SeriesMap {
  const close = bars.map((bar) => bar.close);
  const period = integer(parameters, "period", 20, 4);
  const smooth = ema(close, 4);
  const detrended = close.map((value, index) => smooth[index] === null ? null : value - (smooth[index] as number));
  const inPhase: NullableNumber[] = Array(close.length).fill(null);
  const quadrature: NullableNumber[] = Array(close.length).fill(null);
  for (let index = 3; index < close.length; index++) {
    if ([index, index - 1, index - 2, index - 3].every((cursor) => detrended[cursor] !== null)) {
      inPhase[index] = detrended[index - 2];
      quadrature[index] = 0.0962 * (detrended[index] as number)
        + 0.5769 * (detrended[index - 2] as number)
        - 0.5769 * (detrended[index - 1] as number)
        - 0.0962 * (detrended[index - 3] as number);
    }
  }
  const phase = inPhase.map((value, index) => value === null || quadrature[index] === null ? null : Math.atan2(quadrature[index] as number, value));
  const amplitude = inPhase.map((value, index) => value === null || quadrature[index] === null ? null : Math.sqrt(value ** 2 + (quadrature[index] as number) ** 2));
  if (title === "Hilbert Transform Dominant Cycle Period") {
    const value: NullableNumber[] = Array(close.length).fill(null);
    let previous: number | null = null;
    for (let index = 1; index < close.length; index++) {
      if (phase[index] === null || phase[index - 1] === null) continue;
      const rawDelta = (phase[index - 1] as number) - (phase[index] as number);
      const delta = ((rawDelta % (2 * Math.PI)) + 2 * Math.PI) % (2 * Math.PI);
      const estimate = delta < 2 * Math.PI / 50 ? 50 : Math.max(6, Math.min(50, 2 * Math.PI / delta));
      previous = previous === null ? estimate : 0.2 * estimate + 0.8 * previous;
      value[index] = previous;
    }
    return { value };
  }
  if (title === "Hilbert Transform Dominant Cycle Phase") return { phase };
  if (title === "Hilbert Transform Phasor Components") return { in_phase: inPhase, quadrature, amplitude, phase };
  if (title === "Hilbert Transform SineWave") return { sine: phase.map((value) => value === null ? null : Math.sin(value)), lead_sine: phase.map((value) => value === null ? null : Math.sin(value + Math.PI / 4)) };
  if (title === "Hilbert Transform Trend/Cycle Mode") {
    const trend = ema(close, period);
    return { mode: close.map((value, index) => trend[index] === null || amplitude[index] === null ? null : Math.abs(value - (trend[index] as number)) > 1.5 * (amplitude[index] as number) ? "trend" : "cycle"), trend, amplitude };
  }
  const alpha = (Math.cos(2 * Math.PI / period) + Math.sin(2 * Math.PI / period) - 1) / Math.cos(2 * Math.PI / period);
  const highPass = Array(close.length).fill(0) as number[];
  for (let index = 2; index < close.length; index++) {
    highPass[index] = (1 - alpha / 2) ** 2 * (close[index] - 2 * close[index - 1] + close[index - 2])
      + 2 * (1 - alpha) * highPass[index - 1]
      - (1 - alpha) ** 2 * highPass[index - 2];
  }
  if (title === "Ehlers Decycler") return { high_pass: highPass, value: close.map((value, index) => value - highPass[index]) };
  if (title === "Ehlers Cyber Cycle") return { value: ema(highPass, period) };
  if (title === "Ehlers Roofing Filter") {
    // Reuse the native Super Smoother after the high-pass stage.
    const filteredBars = bars.map((bar, index) => ({ ...bar, close: highPass[index] }));
    return { high_pass: highPass, value: trendSmoothing("Ehlers Super Smoother Filter", filteredBars, { period: Math.max(4, Math.floor(period / 2)) }).value };
  }
  throw new ContractError(`unsupported cycle topic: ${title}`);
}

